import { scope } from "arktype";

/**
 * Directory tree node schema definitions, declared inside a `scope` so that
 * the node type can reference itself recursively via its exported name.
 *
 *  - `name`     : non-empty string
 *  - `size`     : optional positive integer (files only)
 *  - `children` : optional array of nested nodes (directories only)
 *
 * The disjunction below enforces that `size` and `children` are mutually
 * exclusive: a node with a `size` may not contain `children`, and vice versa.
 */
export const treeScope = scope({
  directoryNode: {
    name: "string > 0",
    "children?": "directoryNode[]",
  },
  fileNode: {
    name: "string > 0",
    size: "0 < integer",
  },
  directoryTreeNode: "directoryNode | fileNode",
}).export();

const { directoryTreeNode } = treeScope;

/**
 * Validate an arbitrary input value as a directory tree node.
 *
 * Uses ArkType's `.assert(...)` so any deviation from the schema throws a
 * `TraversalError` (an `ArkError`) instead of returning an `ArkErrors` object.
 *
 * @param input - The value to validate (typically parsed JSON).
 * @returns The validated tree node, structurally identical to the input
 *          (ArkType preserves unknown keys and identity for matching input).
 * @throws When `input` does not satisfy the directory tree schema.
 */
export function validateDirectoryTree(input: unknown): unknown {
  return directoryTreeNode.assert(input);
}

export type DirectoryTreeNode = unknown;

import { readFileSync } from "node:fs";
import { validateDirectoryTree } from "./src/validator.js";

/**
 * Read the entire stdin synchronously and parse it as JSON.
 * Throws if the payload is not valid JSON.
 */
function readStdinJson(): unknown {
  const raw = readFileSync(0, "utf8");
  if (raw.trim().length === 0) {
    throw new Error("empty stdin payload");
  }
  return JSON.parse(raw);
}

function main(): void {
  let parsed: unknown;
  try {
    parsed = readStdinJson();
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    process.stdout.write(`INVALID: ${message}\n`);
    return;
  }

  try {
    const validated = validateDirectoryTree(parsed);
    process.stdout.write("VALID\n");
    process.stdout.write(`${JSON.stringify(validated)}\n`);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    process.stdout.write(`INVALID: ${message}\n`);
  }
}

main();

